targets.query:
from(bucket: "solar_raw")
  |> range(start: v.timeRangeStart, stop: v.timeRangeStop)
  |> filter(fn: (r) => r._measurement == "solar" and r._field == "value")
  |> filter(fn: (r) => r.device == "${device}")
  |> filter(fn: (r) =>
      (r.component == "house" and r.metric == "energy_today") or
      (r.component == "grid" and r.metric == "buy_today")
  )
  |> map(fn: (r) => ({
      r with _field: if r.component == "house" then "house" else "buy"
  }))
  |> aggregateWindow(every: 1d, fn: last, createEmpty: false)
  |> group(columns: ["_field"])
  |> sum()
  |> map(fn: (r) => ({ _time: now(), _field: r._field, _value: r._value }))
  |> pivot(rowKey: ["_time"], columnKey: ["_field"], valueColumn: "_value")
  |> map(fn: (r) => {
      h = if exists r.house then float(v: r.house) else 0.0
      b = if exists r.buy then float(v: r.buy) else 0.0
      raw = if h > 0.0 then (h - b) / h * 100.0 else 0.0
      pct = if raw < 0.0 then 0.0 else raw
      return { _time: r._time, _field: "Self", _value: pct }
  })
